<template><div v-if="open" class="modal-backdrop" @keydown.esc="!busy&&$emit('cancel')"><div class="modal" role="dialog" aria-modal="true"><h2>{{ title }}</h2><p v-if="message">{{ message }}</p><p v-else>This action cannot be undone.</p><div class="modal-actions"><button @click="$emit('cancel')" :disabled="busy">Cancel</button><button class="danger" @click="$emit('confirm')" :disabled="busy">{{ busy?'Deleting…':'Delete' }}</button></div></div></div></template>
<script setup>defineProps({open:Boolean,title:{type:String,default:'Delete record?'},message:String,busy:Boolean});defineEmits(['cancel','confirm'])</script>
